def divisible_by_digits(startnum, endnum):
    result = []
    for num in range(startnum, endnum + 1):
        s_num = str(num)
        # Skip numbers containing 0 to avoid DivisionByZero
        if '0' in s_num:
            continue

        is_valid = True
        for digit in s_num:
            if num % int(digit) != 0:
                is_valid = False
                break

        if is_valid:
            result.append(num)
    return result

